input.content:
// Follow-up gate for the customer-support assistant (WhatsApp Business + SMS).
// Decides whether the assistant may send a follow-up to a customer.
// State is kept in memory only and is lost on restart.

const DAY_MS = 24 * 60 * 60 * 1000;

// Opt-out keywords (carrier / CTIA list). Only a whole message counts.
const STOP_WORDS = new Set(["STOP", "STOPALL", "UNSUBSCRIBE", "CANCEL", "END", "QUIT", "OPTOUT", "REVOKE"]);
// Opt-in keywords that lift an opt-out.
const START_WORDS = new Set(["START", "UNSTOP"]);

// userId -> { lastInboundAt, statusAt, optedOut }   (times in epoch ms)
const users = new Map();

// Returns "stop", "start", or null. Ignores case, spaces, punctuation and
// zero-width characters, and folds full-width letters, so "  Stop!! " and
// "ＳＴＯＰ" both match. A keyword inside a longer sentence does not match.
function keywordOf(text) {
  if (typeof text !== "string") return null;
  const letters = text.normalize("NFKC").replace(/[^\p{L}\p{N}]/gu, "").toUpperCase();
  if (STOP_WORDS.has(letters)) return "stop";
  if (START_WORDS.has(letters)) return "start";
  return null;
}

function block(rule) {
  return { allowed: false, rule };
}

export function onInbound(userId, text, at) {
  if (!(at instanceof Date) || Number.isNaN(at.getTime())) {
    throw new TypeError("onInbound: at must be a valid Date");
  }
  const t = at.getTime();
  const rec = users.get(userId) ?? { lastInboundAt: t, statusAt: null, optedOut: false };

  if (t > rec.lastInboundAt) rec.lastInboundAt = t;

  const kw = keywordOf(text);
  // Apply an opt-in/opt-out only if it is not older than the last one applied,
  // so late-arriving messages cannot undo a newer STOP.
  if (kw && (rec.statusAt === null || t >= rec.statusAt)) {
    rec.statusAt = t;
    rec.optedOut = kw === "stop";
  }

  users.set(userId, rec);
}

export function check(userId, type, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError("check: now must be a valid Date");
  }
  if (type !== "freeform" && type !== "template") {
    return block("unknown-message-type");
  }

  // Never-contacted customers: the assistant may only follow up on a conversation they started.
  const rec = users.get(userId);
  if (!rec) return block("no-prior-contact");

  // Honor STOP until the customer sends START or UNSTOP. Applies to all message types.
  if (rec.optedOut) return block("opted-out");

  // Free text is allowed only inside the 24-hour customer-service window that
  // opens with the customer's last inbound message. Templates are exempt.
  if (type === "freeform" && now.getTime() - rec.lastInboundAt >= DAY_MS) {
    return block("freeform-window-closed");
  }

  return { allowed: true, rule: null };
}

input.command:
d=$(mktemp -d) && cat > "$d/test.mjs" <<'EOF'
import assert from "node:assert/strict";
import { onInbound, check } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g5-3/bot.mjs";

const H = 3600e3, D = 24 * H;
const T0 = new Date("2026-10-20T10:00:00Z");
const at = (ms) => new Date(T0.getTime() + ms);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log("ok -", name); };

ok("never-contacted user blocked for both types", () => {
  assert.deepEqual(check("new1", "freeform", at(0)), { allowed: false, rule: "no-prior-contact" });
  assert.deepEqual(check("new1", "template", at(0)), { allowed: false, rule: "no-prior-contact" });
});

ok("freeform allowed inside 24h, blocked at and after 24h", () => {
  onInbound("u1", "my bill is wrong", at(0));
  assert.deepEqual(check("u1", "freeform", at(D - 1)), { allowed: true, rule: null });
  assert.deepEqual(check("u1", "freeform", at(D)), { allowed: false, rule: "freeform-window-closed" });
});

ok("template allowed after window closes", () => {
  assert.deepEqual(check("u1", "template", at(5 * D)), { allowed: true, rule: null });
});

ok("unknown type fails closed", () => {
  assert.deepEqual(check("u1", "promo", at(0)), { allowed: false, rule: "unknown-message-type" });
});

const stopVariants = ["STOP", "stop", "  Stop!! ", "stop.", "*STOP*", "S.T.O.P", "ＳＴＯＰ", "Stop All", "stopall", "unsubscribe", "Cancel", "END", "quit", "optout", "revoke", "​STOP​"];
for (const [i, v] of stopVariants.entries()) {
  ok(`STOP variant ${JSON.stringify(v)} opts out`, () => {
    const u = `s${i}`;
    onInbound(u, "hi", at(0));
    onInbound(u, v, at(1000));
    assert.equal(check(u, "template", at(2000)).rule, "opted-out");
    assert.equal(check(u, "freeform", at(2000)).rule, "opted-out");
  });
}

const normal = ["please stop by the store tomorrow", "I can't stop thinking about my bill", "don't stop", "no, stop", "the stop was late", "start my plan", "Let's start", "ending the call"];
for (const [i, v] of normal.entries()) {
  ok(`ordinary sentence ${JSON.stringify(v)} is not a keyword`, () => {
    const u = `n${i}`;
    onInbound(u, v, at(0));
    assert.deepEqual(check(u, "freeform", at(1000)), { allowed: true, rule: null });
  });
}

ok("START and UNSTOP restore messaging; freeform window still applies", () => {
  onInbound("r1", "STOP", at(0));
  assert.equal(check("r1", "template", at(1)).rule, "opted-out");
  onInbound("r1", "Start", at(2 * H));
  assert.deepEqual(check("r1", "template", at(3 * H)), { allowed: true, rule: null });
  assert.deepEqual(check("r1", "freeform", at(3 * H)), { allowed: true, rule: null });
  onInbound("r1", "stop", at(4 * H));
  onInbound("r1", "UNSTOP!", at(5 * H));
  assert.deepEqual(check("r1", "template", at(6 * H)), { allowed: true, rule: null });
  assert.deepEqual(check("r1", "freeform", at(6 * H)), { allowed: true, rule: null });
  assert.equal(check("r1", "freeform", at(5 * H + 25 * H)).rule, "freeform-window-closed");
});

ok("YES is not an opt-in keyword (stays opted out)", () => {
  onInbound("y1", "STOP", at(0));
  onInbound("y1", "YES", at(1));
  assert.equal(check("y1", "template", at(2)).rule, "opted-out");
});

ok("out-of-order late START does not undo newer STOP", () => {
  onInbound("o1", "STOP", at(5000));
  onInbound("o1", "START", at(1000));
  assert.equal(check("o1", "template", at(6000)).rule, "opted-out");
});

ok("out-of-order inbound does not shrink the window", () => {
  onInbound("w1", "hello", at(10 * H));
  onInbound("w1", "older", at(0));
  assert.deepEqual(check("w1", "freeform", at(10 * H + D - 1)), { allowed: true, rule: null });
});

ok("users are independent", () => {
  onInbound("a1", "STOP", at(0));
  onInbound("a2", "hello", at(0));
  assert.equal(check("a1", "template", at(1)).rule, "opted-out");
  assert.deepEqual(check("a2", "template", at(1)), { allowed: true, rule: null });
});

ok("invalid dates throw", () => {
  assert.throws(() => onInbound("x", "hi", "2026-10-20"), TypeError);
  assert.throws(() => check("x", "template", new Date("nope")), TypeError);
});

console.log(`\n${n} checks passed`);
EOF
node "$d/test.mjs"; echo "exit=$?"; rm -rf "$d"
